tbody></table></div></section>
<section class="card billing-panel"><h2>Classificação dos centros</h2><div class="table-wrap"><table><thead><tr><th>Centro</th><th>Unidade</th><th>Cliente associado</th><th>Tipo</th></tr></thead><tbody><?php foreach($catalogs['centers']as$c):?><tr><td><?=$e($c['cost_center_code'].' — '.$c['name'])?></td><td><?=$e($c['unit_name']?:'Sem unidade operacional')?></td><td><?=$e($c['client_name']?:'CENTRO DE CUSTO SEM CLIENTE ASSOCIADO')?></td><td><?=$c['client_type']==='internal'?'Interno':($c['client_type']==='external'?'Externo':'Pendente')?></td></tr><?php endforeach?></tbody></table></div><p>Defina a qual cliente este centro de custo pertence para que o faturamento seja classificado corretamente.</p></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('form[action="/admin/billing/catalog"]');if(!f)return;const label=document.createElement('label');label.textContent='Cliente associado';const select=document.createElement('select');select.name='client_id';select.innerHTML='<option value="">Herdar da unidade / pendente</option>'+<?=json_encode(array_map(fn($c)=>'<option value="'.(int)$c['id'].'">'.htmlspecialchars($c['name'].' — '.($c['client_type']==='internal'?'Interno':'Externo'),ENT_QUOTES,'UTF-8').'</option>',$catalogs['clients']),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>.join('');label.appendChild(select);f.insertBefore(label,f.querySelector('label:nth-last-of-type(2)'));});</script>
